{"command":"python3 -c "
from datasets import load_dataset
dataset = load_dataset('conll2003', split='validation', trust_remote_code=True)
unique = set()
for ex in dataset:
    tokens = ex['tokens']
    tags = ex['ner_tags']
    current = None
    for tok, tag in zip(tokens, tags):
        if tag == 1:
            if current is not None:
                unique.add(' '.join(current))
            current = [tok]
        elif tag == 2:
            if current is not None:
                current.append(tok)
            else:
                # I-PER without B-PER: treat as start? Standard handling - but spec says entity starts with B-PER. Safest: start new entity
                current = [tok]
        else:
            if current is not None:
                unique.add(' '.join(current))
                current = None
    if current is not None:
        unique.add(' '.join(current))
print(len(unique))
print(sorted(list(unique))[:10])
"
","description":"Count unique PER names in CoNLL2003","yield_time_ms":120000}

